func (m *MemStore) GetProfile(_ context.Context, id string) (*ProfileRecord, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if p, ok := m.profiles[id]; ok {
		c := *p
		return &c, nil
	}
	return nil, ErrNotFound
}

func (m *MemStore) UpsertProfile(_ context.Context, rec *ProfileRecord, create bool) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	_, exists := m.profiles[rec.ID]
	if create && exists {
		return ErrDuplicate
	}
	if !create && !exists {
		return ErrNotFound
	}
	c := *rec
	c.UpdatedAt = time.Now()
	if !exists {
		c.CreatedAt = c.UpdatedAt
	}
	m.profiles[rec.ID] = &c
	return nil
}

func (m *MemStore) DeleteProfile(_ context.Context, id string) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, ok := m.profiles[id]; !ok {
		return ErrNotFound
	}
	delete(m.profiles, id)
	delete(m.grants, id)
	return nil
}
